head.script:
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = 0;
    log++;
    if (localStorage.getItem("count")) {
        localStorage.setItem("count", 2);
    } else {
        localStorage.setItem("count", log);
    }
    //alert(1234);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
